/**
 * VANOWARNA — interactive CV terminal (entry point).
 *
 * All content comes from content/cv.json. index.html already contains a
 * static copy of the CV (generated by tools/build.mjs) for search engines
 * and for visitors without JavaScript; this script replaces it with the
 * live terminal once the content has loaded.
 */

import { buildCommands, helpLines, summaryLines, line, blank } from "./commands.js";
import { Terminal } from "./terminal.js";
import { createAssistant } from "./assistant.js";
import { createSoundtrack } from "./audio.js";
import { getPref, setPref, prefersReducedMotion, isTouchDevice, isSmallScreen } from "./prefs.js";

const CONTENT_URL = "content/cv.json";
const PROMPT = "visitor@cv>";

const $ = (id) => document.getElementById(id);
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const root = document.documentElement;
const inputEl = $("command-input");
const chipBar = $("chip-bar");
const soundButton = $("sound-toggle");
const fxButton = $("fx-toggle");

const terminal = new Terminal({ body: $("terminal-body"), output: $("output"), promptText: PROMPT });

/* ---------- Sound & visual effects ---------- */

const setToggle = (button, on) => {
    button.setAttribute("aria-pressed", String(on));
    button.querySelector(".toggle-state").textContent = on ? "on" : "off";
};

const soundtrack = createSoundtrack($("bg-audio"), (on) => setToggle(soundButton, on));

let scene = null;
let fxOn = getPref("fx", "on") === "on";

const applyFx = () => {
    root.classList.toggle("fx-off", !fxOn);
    setToggle(fxButton, fxOn);
    if (scene) scene.setEnabled(fxOn);
};

const loadScene = async (blipCount) => {
    if (scene || !fxOn) return;
    try {
        const { createScene } = await import("./scene.js");
        scene = createScene($("scene"), {
            blipCount,
            lowPower: isTouchDevice() || isSmallScreen(),
            staticFrame: prefersReducedMotion(),
            level: soundtrack.level,
        });
        root.classList.add("scene-ready");
    } catch {
        /* WebGL unavailable: the CSS backdrop stands on its own */
    }
};

const setFx = (on, blipCount) => {
    fxOn = on;
    setPref("fx", on ? "on" : "off");
    applyFx();
    if (on) loadScene(blipCount);
};

/* ---------- Cursor glow (pointer devices only) ---------- */

const cursorGlow = $("cursor-glow");
if (!isTouchDevice()) {
    window.addEventListener(
        "pointermove",
        (e) => {
            cursorGlow.style.transform = `translate3d(${e.clientX}px, ${e.clientY}px, 0)`;
        },
        { passive: true }
    );
}

/* ---------- Title glitch (one timer, started once) ---------- */

const startGlitch = () => {
    const title = document.querySelector(".glitch");
    if (!title || prefersReducedMotion()) return;
    const burst = () => {
        if (fxOn && !document.hidden) {
            title.classList.add("glitch-active");
            setTimeout(() => title.classList.remove("glitch-active"), 180 + Math.random() * 220);
        }
        setTimeout(burst, 4000 + Math.random() * 6000);
    };
    setTimeout(burst, 2500);
};

/* ---------- Keep the layout inside the visible viewport ----------
   On phones the on-screen keyboard shrinks the visual viewport without
   resizing the layout viewport; track it so the prompt stays in view. */

const trackViewport = () => {
    const viewport = window.visualViewport;
    if (!viewport) return;
    const update = () => {
        root.style.setProperty("--viewport-height", `${viewport.height}px`);
        window.scrollTo(0, 0);
    };
    viewport.addEventListener("resize", update);
    update();
};

/* ---------- Boot ---------- */

const boot = async (cv) => {
    terminal.clear();
    if (!prefersReducedMotion()) {
        const width = isSmallScreen() ? 18 : 30;
        const bar = terminal.append(line("", "dim"));
        const text = bar.querySelector(".text");
        const steps = 10;
        for (let i = 1; i <= steps; i++) {
            const filled = Math.round((i / steps) * width);
            text.textContent = `loading cv  [${"█".repeat(filled)}${"░".repeat(width - filled)}]  ${i * 10}%`;
            await sleep(35 + Math.random() * 35);
        }
        await sleep(120);
        terminal.clear();
    }

    const hint = isTouchDevice()
        ? "Tap a command below, or tap the prompt to ask a question."
        : "Type 'help', pick a command below, or just ask a question.";
    await terminal.print([...summaryLines(cv), blank(), line(hint, "dim")], { stream: true });
    terminal.body.scrollTop = 0;
};

/* ---------- Commands ---------- */

const levenshtein = (a, b) => {
    const row = Array.from({ length: b.length + 1 }, (_, i) => i);
    for (let i = 1; i <= a.length; i++) {
        let previous = row[0];
        row[0] = i;
        for (let j = 1; j <= b.length; j++) {
            const current = row[j];
            row[j] = Math.min(row[j] + 1, row[j - 1] + 1, previous + (a[i - 1] === b[j - 1] ? 0 : 1));
            previous = current;
        }
    }
    return row[b.length];
};

const start = (cv) => {
    const commands = buildCommands(cv);
    const assistant = createAssistant(cv, commands);
    const blipCount = (cv.sections || []).reduce((n, s) => n + (s.entries ? s.entries.length : 0), 0);

    const builtins = [
        ["ask", "ask a question in plain English"],
        ["sound", "toggle the soundtrack"],
        ["fx", "toggle visual effects"],
        ["help", "show this list"],
        ["clear", "clear the terminal"],
    ];
    const allNames = [...commands.list.flatMap((c) => [c.name, ...c.aliases]), ...builtins.map(([n]) => n)];

    /* Chips are generated from the content, so new sections appear automatically. */
    const chip = (name, extraClass = "") => {
        const button = document.createElement("button");
        button.type = "button";
        button.className = `chip ${extraClass}`.trim();
        button.dataset.cmd = name;
        button.textContent = name;
        return button;
    };
    chipBar.replaceChildren(
        chip("ask", "chip--accent"),
        ...commands.list.map((c) => chip(c.name)),
        chip("clear", "chip--danger")
    );

    const answer = async (question, anchor) => {
        const pending = terminal.append(line(assistant.isRemote ? "thinking…" : "searching the CV…", "dim pending"));
        terminal.scrollToEnd();
        const lines = await assistant.ask(question);
        pending.remove();
        await terminal.print(lines, { anchor });
    };

    let busy = false;

    const run = async (raw) => {
        const input = raw.trim();
        if (!input || busy) return;
        busy = true;
        try {
            const [word, ...rest] = input.split(/\s+/);
            const name = word.toLowerCase();
            const argument = rest.join(" ");

            if (name === "clear") {
                terminal.clear();
                return;
            }

            const echo = terminal.echo(input);
            if (scene) scene.ping();

            const command = rest.length ? null : commands.find(name);
            if (command) {
                await terminal.print(command.run(), { stream: command.name !== "all", anchor: echo });
            } else if (name === "help" && !rest.length) {
                await terminal.print(helpLines(commands, builtins), { anchor: echo });
            } else if (name === "sound" && !rest.length) {
                const on = await soundtrack.toggle();
                await terminal.print([line(`soundtrack ${on ? "on" : "off"}`, "dim")]);
            } else if (name === "fx" && !rest.length) {
                setFx(!fxOn, blipCount);
                await terminal.print([line(`visual effects ${fxOn ? "on" : "off"}`, "dim")]);
            } else if (name === "ask") {
                await answer(argument, echo);
            } else if (rest.length || input.endsWith("?")) {
                // Anything that reads like a sentence is treated as a question.
                await answer(input, echo);
            } else {
                const guess = allNames.find((n) => levenshtein(n, name) <= 2);
                const suggestion = guess ? `did you mean '${guess}'?` : "type 'help' for the list";
                await terminal.print([line(`command not found: ${input} — ${suggestion}`, "muted")]);
            }
        } finally {
            busy = false;
        }
    };

    /* Input: history, tab completion */
    const history = [];
    let historyIndex = 0;

    inputEl.maxLength = assistant.maxLength + 4; // room for the "ask " prefix
    inputEl.addEventListener("keydown", (e) => {
        if (e.key === "Enter") {
            const value = inputEl.value;
            inputEl.value = "";
            if (value.trim()) {
                history.push(value);
                historyIndex = history.length;
            }
            run(value);
        } else if (e.key === "ArrowUp" || e.key === "ArrowDown") {
            if (!history.length) return;
            e.preventDefault();
            const step = e.key === "ArrowUp" ? -1 : 1;
            historyIndex = Math.max(0, Math.min(history.length, historyIndex + step));
            inputEl.value = history[historyIndex] || "";
        } else if (e.key === "Tab" && inputEl.value && !inputEl.value.includes(" ")) {
            const matches = allNames.filter((n) => n.startsWith(inputEl.value.toLowerCase()));
            if (matches.length === 1) {
                e.preventDefault();
                inputEl.value = matches[0];
            }
        }
    });

    chipBar.addEventListener("click", (e) => {
        const button = e.target.closest(".chip");
        if (!button) return;
        if (button.dataset.cmd === "ask") {
            inputEl.placeholder = "ask me anything about my work…";
            inputEl.focus();
            return;
        }
        run(button.dataset.cmd);
        // Refocusing on a phone would pop the keyboard over the answer.
        if (!isTouchDevice()) inputEl.focus();
    });

    /* Clicking empty terminal space focuses the prompt (without breaking text selection or links). */
    terminal.body.addEventListener("click", (e) => {
        if (e.target.closest("a, button")) return;
        if (String(window.getSelection())) return;
        if (isTouchDevice() && !e.target.closest(".input-line")) return;
        inputEl.focus();
    });

    soundButton.addEventListener("click", () => soundtrack.toggle());
    fxButton.addEventListener("click", () => setFx(!fxOn, blipCount));

    applyFx();
    startGlitch();
    trackViewport();

    boot(cv).then(() => {
        if (!isTouchDevice()) inputEl.focus({ preventScroll: true });
        // Load the 3D scene only after the terminal is usable.
        const idle = window.requestIdleCallback || ((fn) => setTimeout(fn, 200));
        idle(() => loadScene(blipCount));
    });
};

/* ---------- Go ---------- */

root.classList.add("js");

fetch(CONTENT_URL)
    .then((response) => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return response.json();
    })
    .then(start)
    .catch((error) => {
        // The static CV already in the page stays visible; just say what happened.
        console.error("Could not load CV content:", error);
        terminal.append(blank());
        terminal.append(line("Interactive mode is unavailable right now; the full CV is shown above.", "muted"));
    });
